func TestPlaceContextRawDispatchParsesInput(t *testing.T) {
	path := filepath.Join(t.TempDir(), "invalid.json")
	if err := os.WriteFile(path, []byte("{invalid"), 0o600); err != nil {
		t.Fatal(err)
	}
	err := run(context.Background(), []string{place.RawContextCommand, "--input", path})
	if output.IsUsage(err) {
		t.Fatalf("raw context command returned a usage error: %v", err)
	}
	var syntaxErr *json.SyntaxError
	if !errors.As(err, &syntaxErr) || !strings.HasPrefix(err.Error(), "read place input:") {
		t.Fatalf("raw context error = %v, want an input JSON parse error", err)
	}
}

func TestCommandContextSecondInterruptTerminates(t *testing.T) {
	if os.Getenv("PHOTOSCRAWL_TEST_SIGNAL_CHILD") == "1" {
		ctx, stop := commandContext()
		defer stop()
		fmt.Println("ready")
		<-ctx.Done()
		fmt.Println("canceled")
		select {}
	}
	executable, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	cmd := exec.CommandContext(ctx, executable, "-test.run=^TestCommandContextSecondInterruptTerminates$")
	cmd.Env = append(os.Environ(), "PHOTOSCRAWL_TEST_SIGNAL_CHILD=1")
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		t.Fatal(err)
	}
	if err := cmd.Start(); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = cmd.Process.Kill() })
	scanner := bufio.NewScanner(stdout)
	if !scanner.Scan() || scanner.Text() != "ready" {
		t.Fatal("child did not install signal handling")
	}
	if err := cmd.Process.Signal(os.Interrupt); err != nil {
		t.Fatal(err)
	}
	if !scanner.Scan() || scanner.Text() != "canceled" {
		t.Fatal("first interrupt did not cancel the context")
	}
	done := make(chan error, 1)
	go func() { done <- cmd.Wait() }()
	// Allow the cancellation goroutine to unregister before the next signal.
	time.Sleep(50 * time.Millisecond)
	if err := cmd.Process.Signal(os.Interrupt); err != nil {
		t.Fatal(err)
	}
	select {
	case err := <-done:
		if err == nil || ctx.Err() != nil {
			t.Fatalf("second interrupt did not terminate child: %v", err)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("second interrupt was swallowed")
	}
}

func TestWriteVersion(t *testing.T) {
	previous := version
	version = "0.1.0-test"
	t.Cleanup(func() { version = previous })

	var out bytes.Buffer
	if err := writeVersion(&out); err != nil {
		t.Fatalf("writeVersion failed: %v", err)
	}
	if got := out.String(); got != "0.1.0-test\n" {
		t.Fatalf("version output = %q", got)
	}
}

func TestUsageListsPhotoAssistCommands(t *testing.T) {
	err := usage()
	for _, command := range []string{"sheet", "similar", "forgotten", "share-check"} {
		if !strings.Contains(err.Error(), command) {
			t.Fatalf("usage does not list %q: %v", command, err)
		}
	}
}

func TestRankRejectsLimitFlag(t *testing.T) {
	err := run(context.Background(), []string{"rank", "--limit", "1"})
	if !output.IsUsage(err) || !strings.Contains(err.Error(), "flag provided but not defined: -limit") {
		t.Fatalf("rank --limit error = %v, want usage error", err)
	}
}

func TestInitExistingArchiveDoesNotRequireSnapshotScratchSpace(t *testing.T) {
	database := filepath.Join(t.TempDir(), "photos.sqlite")
	if _, err := archive.Init(context.Background(), archive.Paths{Database: database}); err != nil {
		t.Fatal(err)
	}
	blocked := filepath.Join(t.TempDir(), "not-a-directory")
	if err := os.WriteFile(blocked, []byte("synthetic"), 0o600); err != nil {
		t.Fatal(err)
	}
	t.Setenv("TMPDIR", blocked)
	if err := run(context.Background(), []string{"init", "--db", database, "--json"}); err != nil {
		t.Fatalf("init of a quiescent archive required snapshot scratch space: %v", err)
	}
}

func TestStatusFullCheckUsesSnapshotScratchSpace(t *testing.T) {
	database := filepath.Join(t.TempDir(), "photos.sqlite")
	if _, err := archive.Init(context.Background(), archive.Paths{Database: database}); err != nil {
		t.Fatal(err)
	}
	if err := run(context.Background(), []string{"status", "--db", database, "--full-check", "--json"}); err != nil {
		t.Fatalf("status --full-check: %v", err)
	}
	blocked := filepath.Join(t.TempDir(), "not-a-directory")
	if err := os.WriteFile(blocked, []byte("synthetic"), 0o600); err != nil {
		t.Fatal(err)
	}
	t.Setenv("TMPDIR", blocked)
	err := run(context.Background(), []string{"status", "--db", database, "--full-check", "--json"})
	if err == nil || output.IsUsage(err) || !strings.Contains(err.Error(), "not a directory") {
		t.Fatalf("status --full-check error = %v, want snapshot scratch-space failure", err)
	}
}

func TestJoinedQueryPreservesLauncherArguments(t *testing.T) {
	if got := joinedQuery("hello", []string{"world", "photos"}); got != "hello world photos" {
		t.Fatalf("joined query = %q", got)
	}
	if got := joinedQuery("", []string{"hello", "world"}); got != "hello world" {
		t.Fatalf("positional query = %q", got)
	}
}

func TestPlaceBackfillRunReturnsCanceledDuringRetrySleep(t *testing.T) {
	dir := t.TempDir()
	dbPath := filepath.Join(dir, "photos.sqlite")
	outDir := filepath.Join(dir, "backfill")
	if err := writePlaceBackfillRetryFixture(dbPath, outDir); err != nil {
		t.Fatal(err)
	}

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	errCh := make(chan error, 1)
	started := time.Now()
	go func() {
		errCh <- run(ctx, []string{"place-backfill", "--db", dbPath, "--out", outDir, "--json"})
	}()
	time.Sleep(80 * time.Millisecond)
	cancel()

	select {
	case err := <-errCh:
		if !errors.Is(err, context.Canceled) {
			t.Fatalf("place-backfill run error = %v, want context.Canceled", err)
		}
		if elapsed := time.Since(started); elapsed >= 2*time.Second {
			t.Fatalf("place-backfill ignored cancel for %s", elapsed)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("place-backfill did not return after cancel during retry sleep")
	}
}

func writePlaceBackfillRetryFixture(dbPath, outDir string) error {
	db, err := sql.Open("sqlite", dbPath)
	if err != nil {
		return err
	}
	defer db.Close()
	if _, err := db.Exec(`
create table asset (id text primary key, creation_date text);
create table location_observation (
  asset_id text,
  latitude real,
  longitude real,
  horizontal_accuracy real
);
insert into asset values ('asset:1', '2026-05-30T12:00:00Z');
insert into location_observation values ('asset:1', 52.379189, 4.899431, 8.5);
`); err != nil {
		return err
	}
	for _, name := range []string{"outputs", "errors", "attempts", "logs"} {
		if err := os.MkdirAll(filepath.Join(outDir, name), 0o700); err != nil {
			return err
		}
	}
	manifest := []byte(`[{"index":0,"latitude":52.379189,"longitude":4.899431,"accuracy_meters":8.5}]`)
	if err := os.WriteFile(filepath.Join(outDir, "manifest.json"), manifest, 0o600); err != nil {
		return err
	}
	return os.WriteFile(filepath.Join(outDir, "attempts", "000000.jsonl"), []byte("{}\n"), 0o600)
}

package evalcard

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"sync/atomic"
	"testing"

	"github.com/openclaw/photoscrawl/internal/photos"
)

func TestRunPreservesDistinctModelOutputs(t *testing.T) {
	opts := preparedModelOptions(t)
	opts.Models = []string{"org/vision:latest", "org_vision:latest", "Vision:latest", "vision:latest"}
	opts.Concurrency = len(opts.Models)
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var request ollamaGenerateRequest
		if err := json.NewDecoder(r.Body).Decode(&request); err != nil {
			http.Error(w, err.Error(), http.StatusBadRequest)
			return
		}
		_ = json.NewEncoder(w).Encode(ollamaGenerateResponse{Response: "synthetic: " + request.Model, Done: true})
	}))
	defer server.Close()
	opts.OllamaGenerateURL = server.URL
	result, err := Run(context.Background(), opts)
	if err != nil || result.ModelCallsSucceeded != len(opts.Models) {
		t.Fatalf("run = %#v, %v", result, err)
	}
	files, err := os.ReadDir(filepath.Join(opts.OutputDir, "raw"))
	if err != nil {
		t.Fatal(err)
	}
	if len(files) != len(opts.Models) {
		t.Fatalf("retained %d model outputs after %d successful calls", len(files), result.ModelCallsSucceeded)
	}
	seen := map[string]bool{}
	for _, file := range files {
		data, err := os.ReadFile(filepath.Join(opts.OutputDir, "raw", file.Name()))
		if err != nil {
			t.Fatal(err)
		}
		var out storedModelOutput
		if err := json.Unmarshal(data, &out); err != nil {
			t.Fatalf("corrupt model evidence: %v", err)
		}
		if out.Response != "synthetic: "+out.Model || seen[out.Model] {
			t.Fatalf("overwritten or mismatched model evidence: %#v", out)
		}
		seen[out.Model] = true
	}
	for _, model := range opts.Models {
		if !seen[model] {
			t.Errorf("missing output for %s", model)
		}
	}
}

func TestRunUsesBuiltInPromptOutsideCheckout(t *testing.T) {
	opts, _ := evalRunOptions(t)
	opts.PromptPath = ""
	t.Chdir(t.TempDir())
	if _, err := Run(context.Background(), opts); err != nil {
		t.Fatalf("default prompt depends on checkout: %v", err)
	}
}

func preparedModelOptions(t *testing.T) Options {
	t.Helper()
	opts, _ := evalRunOptions(t)
	asset := photos.Asset{LocalIdentifier: "synthetic", MediaType: "image"}
	opts.Provider = budgetProvider{[]photos.Asset{asset}}
	opts.Models = []string{"fixture"}
	opts.Concurrency = 1
	if err := os.MkdirAll(opts.CacheDir, 0o700); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(opts.CacheDir, cacheName(asset)), []byte("synthetic original"), 0o600); err != nil {
		t.Fatal(err)
	}
	oldRender, oldMetadata := renderEvalImage, readEvalMetadata
	t.Cleanup(func() { renderEvalImage, readEvalMetadata = oldRender, oldMetadata })
	renderEvalImage = func(_ context.Context, _, dest string, _ float64) error {
		return os.WriteFile(dest, []byte("synthetic image"), 0o600)
	}
	readEvalMetadata = func(context.Context, string) (map[string]any, error) {
		return map[string]any{"synthetic": true}, nil
	}
	return opts
}

func TestRunStopsWhenModelOutputCannotBePersisted(t *testing.T) {
	opts := preparedModelOptions(t)
	opts.Models = []string{"fixture", "second", "third"}
	var calls atomic.Int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		calls.Add(1)
		_, _ = w.Write([]byte(`{"response":"synthetic card","done":true}`))
	}))
	defer server.Close()
	opts.OllamaGenerateURL = server.URL
	blocked := modelOutputPath(opts.OutputDir, "E001", "fixture")
	if err := os.MkdirAll(blocked, 0o700); err != nil {
		t.Fatal(err)
	}
	_, err := Run(context.Background(), opts)
	if err == nil || !strings.Contains(err.Error(), "write model output") {
		t.Fatalf("lost persistence failure: %v", err)
	}
	if calls.Load() != 1 {
		t.Fatalf("continued after evidence write failure: %d calls", calls.Load())
	}
	if _, err := os.Stat(filepath.Join(opts.OutputDir, "summary.json")); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("summary exists after evidence write failure: %v", err)
	}
}

func TestRunRetainsProviderFailuresAsEvidence(t *testing.T) {
	opts := preparedModelOptions(t)
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		http.Error(w, "synthetic provider failure", http.StatusServiceUnavailable)
	}))
	defer server.Close()
	opts.OllamaGenerateURL = server.URL
	result, err := Run(context.Background(), opts)
	if err != nil || result.ModelCallsFailed != 1 || result.ModelCallsSucceeded != 0 {
		t.Fatalf("provider failure result = %#v, %v", result, err)
	}
	data, err := os.ReadFile(modelOutputPath(opts.OutputDir, "E001", "fixture"))
	if err != nil || !strings.Contains(string(data), "synthetic provider failure") {
		t.Fatalf("missing failure evidence: %s, %v", data, err)
	}
}

func TestRunReturnsCancellationFromLastPreparation(t *testing.T) {
	opts := preparedModelOptions(t)
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	renderEvalImage = func(context.Context, string, string, float64) error {
		cancel()
		return context.Canceled
	}
	if _, err := Run(ctx, opts); !errors.Is(err, context.Canceled) {
		t.Fatalf("cancellation became a successful empty run: %v", err)
	}
}

func TestRunReturnsCancellationDuringModelCall(t *testing.T) {
	opts := preparedModelOptions(t)
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		cancel()
		_, _ = w.Write([]byte(`{"response":"synthetic card","done":true}`))
	}))
	defer server.Close()
	opts.OllamaGenerateURL = server.URL
	if _, err := Run(ctx, opts); !errors.Is(err, context.Canceled) {
		t.Fatalf("model cancellation became a completed run: %v", err)
	}
}

