func TestCrawlRejectsMissingOrDuplicateResourceSourceIdentifiers(t *testing.T) {
	t.Parallel()
	ctx := context.Background()
	libraryPath := filepath.Join(t.TempDir(), "Fixture Photos Library.photoslibrary")
