// This test driver keeps the real native bridge alive across late callbacks.
package main

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/openclaw/photoscrawl/internal/photos"
)

func main() {
	root := os.Getenv("PHOTOSCRAWL_NATIVE_FIXTURE_DIR")
	if _, err := os.Stat(filepath.Join(root, "loaded")); err != nil {
		panic("native fixture not loaded")
	}
	destination := os.Args[1]
	mode := os.Getenv("PHOTOSCRAWL_NATIVE_FIXTURE_MODE")
	if strings.HasPrefix(mode, "limited-") {
		runLimited(root, destination, mode)
		return
	}
	ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
	defer cancel()
	if err := photos.ExportOriginalResource(ctx, "synthetic", destination, false); !errors.Is(err, context.DeadlineExceeded) {
		panic(fmt.Sprintf("deadline error: %v", err))
	}
	if os.Getenv("PHOTOSCRAWL_NATIVE_FIXTURE_MODE") == "retry" {
		if err := photos.ExportOriginalResource(context.Background(), "synthetic", destination, false); err != nil {
			panic(err)
		}
	}
	deadline := time.Now().Add(5 * time.Second)
	for {
		if _, err := os.Stat(filepath.Join(root, "late")); err == nil {
			break
		}
		if time.Now().After(deadline) {
			panic("late callback did not arrive")
		}
		time.Sleep(5 * time.Millisecond)
	}
	fmt.Println("deadline propagated; late callback completed safely")
}

func runLimited(root, destination, mode string) {
	var limit int64
	switch mode {
	case "limited-exact", "limited-cancel":
		limit = 18
	case "limited-over-single", "limited-over-chunked":
		limit = 17
	default:
		panic("unknown limited fixture mode")
	}
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	result := make(chan error, 1)
	go func() {
		result <- photos.ExportOriginalResourceLimited(ctx, "synthetic", destination, false, limit)
	}()
	if mode == "limited-cancel" {
		waitMarker(root, "partial")
		staging, err := filepath.Glob(filepath.Join(filepath.Dir(destination), ".photoscrawl-export-*"))
		if err != nil || len(staging) != 1 {
			panic(fmt.Sprintf("partial staging files: %v (%v)", staging, err))
		}
		partial, err := os.ReadFile(staging[0])
		if err != nil || string(partial) != "partial" {
			panic(fmt.Sprintf("partial write: %q (%v)", partial, err))
		}
		cancel()
	}
	var err error
	select {
	case err = <-result:
	case <-time.After(5 * time.Second):
		panic("limited export did not return")
	}
	switch mode {
	case "limited-exact":
		if err != nil {
			panic(fmt.Sprintf("exact budget: %v", err))
		}
	case "limited-over-single", "limited-over-chunked":
		if err == nil || err.Error() != "original resource exceeds byte limit" {
			panic(fmt.Sprintf("byte limit error: %v", err))
		}
	case "limited-cancel":
		if !errors.Is(err, context.Canceled) {
			panic(fmt.Sprintf("cancellation error: %v", err))
		}
		contents, readErr := os.ReadFile(destination)
		staging, globErr := filepath.Glob(filepath.Join(filepath.Dir(destination), ".photoscrawl-export-*"))
		if readErr != nil || string(contents) != "existing-original" || globErr != nil || len(staging) != 0 {
			panic("cancelled export did not preserve destination and remove staging before returning")
		}
		if _, statErr := os.Stat(filepath.Join(root, "late")); !errors.Is(statErr, os.ErrNotExist) {
			panic("late callbacks ran before the post-return barrier")
		}
		if writeErr := os.WriteFile(filepath.Join(root, "export-returned"), nil, 0600); writeErr != nil {
			panic(writeErr)
		}
		waitMarker(root, "late")
	}
	fmt.Printf("limited export %s: expected result; callbacks complete\n", mode)
}

func waitMarker(root, name string) {
	deadline := time.Now().Add(5 * time.Second)
	for {
		_, err := os.Stat(filepath.Join(root, name))
		if err == nil {
			return
		}
		if !errors.Is(err, os.ErrNotExist) {
			panic(err)
		}
		if time.Now().After(deadline) {
			panic("native fixture marker did not arrive: " + name)
		}
		time.Sleep(5 * time.Millisecond)
	}
}

// Synthetic native eval proof: local PNG rendering and a loopback model server.
package main

import (
	"context"
	"crypto/sha256"
	"encoding/json"
	"errors"
	"fmt"
	"image"
	"image/color"
	"image/png"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"sync/atomic"

	"github.com/openclaw/photoscrawl/internal/evalcard"
	"github.com/openclaw/photoscrawl/internal/photos"
)

const identifier = "AAAAAAAA-BBBB-CCCC-DDDD-EEEEEEEEEEEE"

type syntheticProvider struct{}

func (syntheticProvider) Snapshot(context.Context, string) (photos.LibrarySnapshot, error) {
	return photos.LibrarySnapshot{Assets: []photos.Asset{{LocalIdentifier: identifier, MediaType: "image"}}}, nil
}

func main() {
	mode := "default"
	if len(os.Args) > 1 {
		mode = os.Args[1]
	}
	if err := run(mode); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func run(mode string) error {
	root, err := os.MkdirTemp("", "photoscrawl-eval-proof-")
	if err != nil {
		return err
	}
	defer os.RemoveAll(root)
	originals := filepath.Join(root, "library", "originals")
	if err := os.MkdirAll(originals, 0o700); err != nil {
		return err
	}
	file, err := os.Create(filepath.Join(originals, identifier+".png"))
	if err != nil {
		return err
	}
	pixels := image.NewNRGBA(image.Rect(0, 0, 2, 2))
	pixels.SetNRGBA(0, 0, color.NRGBA{R: 255, A: 255})
	err = png.Encode(file, pixels)
	if err := errors.Join(err, file.Close()); err != nil {
		return err
	}
	var calls atomic.Int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		calls.Add(1)
		_, _ = w.Write([]byte(`{"response":"Synthetic photo card","done":true}`))
	}))
	defer server.Close()
	opts := evalcard.Options{
		LibraryPath: filepath.Join(root, "library"), OutputDir: filepath.Join(root, "out"),
		CacheDir: filepath.Join(root, "cache"), Provider: syntheticProvider{},
		Models: []string{"fixture"}, OllamaGenerateURL: server.URL, Limit: 1, Concurrency: 1,
	}
	if mode == "collisions" {
		opts.Models = []string{"org/vision:latest", "org_vision:latest", "Vision:latest", "vision:latest"}
		opts.Concurrency = len(opts.Models)
	}
	if mode == "blocked" {
		opts.PromptPath = filepath.Join(root, "prompt.md")
		if err := os.WriteFile(opts.PromptPath, []byte("Synthetic prompt {{.MetadataJSON}}"), 0o600); err != nil {
			return err
		}
		path := filepath.Join(opts.OutputDir, "raw", fmt.Sprintf("E001__ollama__%x__%s.json", sha256.Sum256([]byte("fixture")), evalcard.PromptVersion))
		if err := os.MkdirAll(path, 0o700); err != nil {
			return err
		}
	}
	if err := os.Chdir(root); err != nil {
		return err
	}
	result, runErr := evalcard.Run(context.Background(), opts)
	if mode == "blocked" {
		if runErr == nil || calls.Load() != 1 {
			return fmt.Errorf("model output failure was lost: calls=%d result=%+v err=%v", calls.Load(), result, runErr)
		}
		if _, err := os.Stat(filepath.Join(opts.OutputDir, "summary.json")); !errors.Is(err, os.ErrNotExist) {
			return fmt.Errorf("summary exists after model evidence failure: %v", err)
		}
		fmt.Println("PASS: native eval reports model evidence write failure and omits summary")
		return nil
	}
	if runErr != nil {
		return runErr
	}
	if result.AssetsPrepared != 1 || result.ModelCallsSucceeded != len(opts.Models) || int(calls.Load()) != len(opts.Models) {
		return fmt.Errorf("native fixture was not evaluated: %+v", result)
	}
	files, err := os.ReadDir(filepath.Join(opts.OutputDir, "raw"))
	if err != nil {
		return err
	}
	if len(files) != len(opts.Models) {
		return fmt.Errorf("retained %d outputs after %d successful calls", len(files), result.ModelCallsSucceeded)
	}
	seen := map[string]bool{}
	for _, file := range files {
		data, err := os.ReadFile(filepath.Join(opts.OutputDir, "raw", file.Name()))
		if err != nil {
			return err
		}
		var out struct{ Model, Response string }
		if err := json.Unmarshal(data, &out); err != nil {
			return err
		}
		if out.Response != "Synthetic photo card" || seen[out.Model] {
			return fmt.Errorf("corrupt or duplicate model output: %+v", out)
		}
		seen[out.Model] = true
	}
	for _, model := range opts.Models {
		if !seen[model] {
			return fmt.Errorf("missing model output: %s", model)
		}
	}
	if mode == "collisions" {
		fmt.Println("PASS: native eval retains four distinct model results for punctuation and case collisions")
		return nil
	}
	fmt.Println("PASS: native eval outside checkout renders synthetic PNG, uses built-in prompt and persists model output")
	return nil
}

package place

import (
	"context"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

func TestCachedPlaceContextKeepsRequestIdentity(t *testing.T) {
	t.Parallel()
	root := t.TempDir()
	input := Input{
		AssetID: "current-asset", ImagePath: "current.png", TakenAt: "2026-09-12T12:00:00Z",
		Location: Coordinate{Latitude: 12, Longitude: 34}, AccuracyMeters: 5,
	}
	inputPath := filepath.Join(root, "input.json")
	if err := writeJSONFile(inputPath, input); err != nil {
		t.Fatal(err)
	}
	path, err := cachePath(root, input, defaultRadiusMeters)
	if err != nil {
		t.Fatal(err)
	}
	cached := Result{
		Input:   Input{AssetID: "previous-asset", ImagePath: "previous.png", TakenAt: "2020-01-01T00:00:00Z", Location: input.Location, AccuracyMeters: input.AccuracyMeters},
		Address: &Address{Formatted: "Synthetic address"}, POIStatus: POIStatusNone,
		GeneratedAt: time.Date(2026, 9, 1, 0, 0, 0, 0, time.UTC),
	}
	if err := writeJSONFile(path, cached); err != nil {
		t.Fatal(err)
	}
	result, err := Run(context.Background(), Options{InputPath: inputPath, CacheDir: root})
	if err != nil {
		t.Fatal(err)
	}
	if !result.Cached || result.Input != input {
		t.Fatalf("cache reused another asset's identity: %#v", result)
	}
	if result.Address.Formatted != cached.Address.Formatted || !result.GeneratedAt.Equal(cached.GeneratedAt) {
		t.Fatalf("provider evidence changed: %#v", result)
	}
}

func TestRenderCardWithoutAddress(t *testing.T) {
	t.Parallel()
	card := RenderCard(Result{POIStatus: POIStatusNone, RadiusMeters: 150})
	if !strings.Contains(card, "Address: unavailable") || !strings.Contains(card, "No named nearby POIs within 150m") {
		t.Fatalf("partial card = %q", card)
	}
}

// Test-only PhotoKit replacement. Linked as a required dylib into proof binaries.
#import <Foundation/Foundation.h>
#import <Photos/Photos.h>
#import <objc/runtime.h>
#include <signal.h>
#include <sys/resource.h>
#include <unistd.h>

static NSString *root;
static NSString *mode;
static int requests;
static NSMutableDictionary *pending;

static void mark(NSString *name) {
  NSString *path = [root stringByAppendingPathComponent:name];
  if (![[NSFileManager defaultManager] createFileAtPath:path contents:[NSData data] attributes:nil]) abort();
}
static void confirmPartial(NSData *expected) {
  NSString *directory = [root stringByAppendingPathComponent:@"out"];
  NSArray *entries = [[NSFileManager defaultManager] contentsOfDirectoryAtPath:directory error:NULL];
  NSUInteger count = 0;
  for (NSString *entry in entries) {
    if (![entry hasPrefix:@".photoscrawl-export-"]) continue;
    NSData *actual = [NSData dataWithContentsOfFile:[directory stringByAppendingPathComponent:entry]];
    if (![actual isEqualToData:expected]) abort();
    count++;
  }
  if (count != 1) abort();
  mark(@"partial");
}
static void waitForMarker(NSString *name) {
  NSString *path = [root stringByAppendingPathComponent:name];
  NSTimeInterval deadline = NSProcessInfo.processInfo.systemUptime + 5;
  while (![[NSFileManager defaultManager] fileExistsAtPath:path]) {
    if (NSProcessInfo.processInfo.systemUptime >= deadline) abort();
    usleep(5000);
  }
}
static PHAuthorizationStatus authorization(id self, SEL selector, ...) {
  return [mode hasPrefix:@"auth"] ? PHAuthorizationStatusNotDetermined : PHAuthorizationStatusAuthorized;
}
static void authorize(id self, SEL selector, PHAccessLevel level, void (^handler)(PHAuthorizationStatus)) {
  mark(@"authorization");
  int64_t delay = [mode isEqual:@"auth-slow"] ? 16 * NSEC_PER_SEC : 300 * NSEC_PER_MSEC;
  dispatch_after(dispatch_time(DISPATCH_TIME_NOW, delay), dispatch_get_global_queue(0, 0), ^{
    handler(PHAuthorizationStatusAuthorized);
    mark(@"late");
  });
}
static id fetch(id self, SEL selector, NSArray *identifiers, id options) {
  if (![identifiers isEqual:@[@"synthetic"]]) abort();
  return @[[NSObject new]];
}
