@interface PCFixtureManager : NSObject
@end
@implementation PCFixtureManager
- (PHAssetResourceDataRequestID)requestDataForAssetResource:(id)resource options:(id)options dataReceivedHandler:(void (^)(NSData *))data completionHandler:(void (^)(NSError *))complete {
  int request = ++requests;
  mark(@"requested");
    if ([mode isEqual:@"write-error"]) {
      signal(SIGXFSZ, SIG_IGN);
      struct rlimit limit = {4, 4};
      if (setrlimit(RLIMIT_FSIZE, &limit) != 0) abort();
    }

  NSData *bytes = [@"synthetic-original" dataUsingEncoding:NSUTF8StringEncoding];
  if ([mode hasPrefix:@"limited-"]) {
    if (((PHAssetResourceRequestOptions *)options).networkAccessAllowed) abort();
    if ([mode isEqual:@"limited-cancel"]) {
      @synchronized(pending) { pending[@(request)] = @[[data copy], [complete copy]]; }
      NSData *partial = [@"partial" dataUsingEncoding:NSUTF8StringEncoding];
      data(partial);
      confirmPartial(partial);
    } else if ([mode isEqual:@"limited-over-single"]) {
      data(bytes);
      complete(nil);
    } else if ([mode isEqual:@"limited-exact"] || [mode isEqual:@"limited-over-chunked"]) {
      NSData *first = [bytes subdataWithRange:NSMakeRange(0, 7)];
      data(first);
      confirmPartial(first);
      data([bytes subdataWithRange:NSMakeRange(7, bytes.length - 7)]);
      complete(nil);
    } else {
      abort();
    }
    mark(@"streamed");
  } else if ([mode isEqual:@"stall"] || [mode isEqual:@"delayed-id"] || ([mode isEqual:@"retry"] && request == 1)) {
    @synchronized(pending) { pending[@(request)] = @[[data copy], [complete copy]]; }
    data([@"partial" dataUsingEncoding:NSUTF8StringEncoding]);
    if ([mode isEqual:@"delayed-id"]) usleep(200000);
  } else if ([mode isEqual:@"error"]) {
    @autoreleasepool {
      complete([NSError errorWithDomain:@"synthetic" code:1 userInfo:@{NSLocalizedDescriptionKey: @"synthetic provider failure"}]);
    }
  } else if ([mode isEqual:@"slow"]) {
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 250 * NSEC_PER_MSEC), dispatch_get_global_queue(0, 0), ^{
      data(bytes);
      complete(nil);
    });
  } else {
    data(bytes);
    complete(nil);
  }
  return request;
}
- (void)cancelDataRequest:(PHAssetResourceDataRequestID)request {
  mark(@"cancelled");
  NSArray *callbacks;
  @synchronized(pending) {
    callbacks = pending[@(request)];
    [pending removeObjectForKey:@(request)];
  }
  if (callbacks == nil) return;
  void (^late)(void) = ^{
    void (^data)(NSData *) = callbacks[0];
    void (^complete)(NSError *) = callbacks[1];
    data([@"late-old-request" dataUsingEncoding:NSUTF8StringEncoding]);
    complete(nil);
    mark(@"late");
  };
  if ([mode isEqual:@"limited-cancel"]) {
    // The Go driver releases this barrier only after the export API returns.
    dispatch_async(dispatch_get_global_queue(0, 0), ^{
      @autoreleasepool {
        waitForMarker(@"export-returned");
        late();
      }
    });
  } else if ([mode isEqual:@"retry"]) {
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 300 * NSEC_PER_MSEC), dispatch_get_global_queue(0, 0), late);
  } else {
    late();
  }
}
@end
static id manager(id self, SEL selector) {
  static PCFixtureManager *instance;
  static dispatch_once_t once;
  dispatch_once(&once, ^{ instance = [PCFixtureManager new]; });
  return instance;
}
static void replace(Class cls, SEL selector, IMP implementation) {
  Method method = class_getClassMethod(cls, selector);
  if (method == NULL) abort();
  method_setImplementation(method, implementation);
}
__attribute__((constructor)) static void installFixture(void) {
  @autoreleasepool {
    const char *directory = getenv("PHOTOSCRAWL_NATIVE_FIXTURE_DIR");
    const char *selected = getenv("PHOTOSCRAWL_NATIVE_FIXTURE_MODE");
    if (directory == NULL || selected == NULL) abort();
    root = [NSString stringWithUTF8String:directory];
    mode = [NSString stringWithUTF8String:selected];
    pending = [NSMutableDictionary new];
    replace(PHPhotoLibrary.class, @selector(authorizationStatus), (IMP)authorization);
    replace(PHPhotoLibrary.class, @selector(authorizationStatusForAccessLevel:), (IMP)authorization);
    replace(PHPhotoLibrary.class, @selector(requestAuthorizationForAccessLevel:handler:), (IMP)authorize);
    replace(PHAsset.class, @selector(fetchAssetsWithLocalIdentifiers:options:), (IMP)fetch);
	  replace(PHAsset.class, @selector(fetchAssetsWithOptions:), (IMP)fetchAllAssets);
	  replace(PHAsset.class, @selector(fetchAssetsInAssetCollection:options:), (IMP)fetchAssetsInCollection);
	  replace(PHCollectionList.class, @selector(fetchTopLevelUserCollectionsWithOptions:), (IMP)fetchTopLevelCollections);
	  replace(PHAssetCollection.class, @selector(fetchAssetCollectionsWithType:subtype:options:), (IMP)fetchAlbumCollections);
	  replace(PHAssetCollection.class, @selector(fetchAssetCollectionsContainingAsset:withType:options:), (IMP)fetchContainingAlbums);
    replace(PHAssetResource.class, @selector(assetResourcesForAsset:), (IMP)resources);
    replace(PHAssetResourceManager.class, @selector(defaultManager), (IMP)manager);
    mark(@"loaded");
  }
}

name: ClawSweeper Dispatch

on:
  issues:
    types: [opened, reopened, edited, labeled, unlabeled]
  issue_comment:
    types: [created, edited]
  pull_request_target: # zizmor: ignore[dangerous-triggers] maintainer-owned external dispatch; no checkout or untrusted PR code execution
    types: [opened, reopened, synchronize, ready_for_review, edited, labeled, unlabeled]

permissions:
  contents: read

concurrency:
  group: clawsweeper-dispatch-${{ github.repository }}-${{ github.event_name }}-${{ github.event.comment.id || github.event.issue.number || github.event.pull_request.number || github.run_id }}-${{ endsWith(github.actor, '[bot]') && (github.event.action == 'labeled' || github.event.action == 'unlabeled') && github.actor || 'dispatchable' }}
  cancel-in-progress: ${{ github.event.action == 'edited' || github.event.action == 'synchronize' || github.event.action == 'ready_for_review' }}

jobs:
  dispatch:
    runs-on: ubuntu-latest
    # id-token proves this repository, event, branch, and run to the queue.
    # The job never checks out or executes pull request code.
    permissions:
      contents: read
      id-token: write
    if: ${{ !(endsWith(github.actor, '[bot]') && (github.event.action == 'labeled' || github.event.action == 'unlabeled')) }}
    env:
      SUPERSEDES_IN_PROGRESS: ${{ (github.event.action == 'edited' || github.event.action == 'synchronize' || github.event.action == 'ready_for_review') && 'true' || 'false' }}
    steps:
      - name: Debounce bursty metadata events
        if: ${{ github.event.action == 'labeled' || github.event.action == 'unlabeled' }}
        run: sleep 20

      - name: Pre-filter ClawSweeper comment
        id: comment_filter
        if: ${{ github.event_name == 'issue_comment' }}
        env:
          COMMENT_BODY: ${{ github.event.comment.body }}
        run: |
          set -euo pipefail
          if [[ "$COMMENT_BODY" == *"<!-- clawsweeper-maintainer-opt-in:"* ]]; then
            echo "is_command=false" >> "$GITHUB_OUTPUT"
            exit 0
          fi
          if grep -Eiq '(^|[[:space:]])@(clawsweeper|openclaw-clawsweeper)\b(\[bot\])?|(^|[[:space:]])/(clawsweeper|review|re-review|rerun([[:space:]]+|-)?review|status|explain|fix|build|implement|create([[:space:]]+|-)?pr|fix([[:space:]]+|-)?issue|autofix|auto([[:space:]]+|-)?fix|automerge|auto([[:space:]]+|-)?merge|approve|stop|autoclose)\b' <<< "$COMMENT_BODY"; then
            echo "is_command=true" >> "$GITHUB_OUTPUT"
          else
            echo "is_command=false" >> "$GITHUB_OUTPUT"
          fi

      - name: Dispatch exact ClawSweeper review
        if: ${{ github.event_name != 'issue_comment' }}
        env:
          TARGET_REPO: ${{ github.repository }}
          TARGET_BRANCH: ${{ github.event.repository.default_branch }}
          ITEM_NUMBER: ${{ github.event.issue.number || github.event.pull_request.number }}
          ITEM_KIND: ${{ github.event_name == 'pull_request_target' && 'pull_request' || 'issue' }}
          SOURCE_EVENT: ${{ github.event_name }}
          SOURCE_ACTION: ${{ github.event.action }}
          TARGET_DISPATCH_URL: https://clawsweeper.openclaw.ai/github/target-dispatch
        run: |
          set -euo pipefail
          source_identity_json="$(node <<'NODE'
          const crypto = require("node:crypto");
          const fs = require("node:fs");
          const event = JSON.parse(fs.readFileSync(process.env.GITHUB_EVENT_PATH, "utf8"));
          const pullRequest = event.pull_request && typeof event.pull_request === "object"
            ? event.pull_request
            : {};
          const issue = event.issue && typeof event.issue === "object" ? event.issue : {};
          const source = process.env.ITEM_KIND === "pull_request" ? pullRequest : issue;
          const headSha = String(pullRequest.head?.sha || "").trim().toLowerCase();
          const baseSha = String(pullRequest.base?.sha || "").trim().toLowerCase();
          const updatedAt = String(pullRequest.updated_at || "").trim();
          const queueClaim = {};
          const result = { queue_claim: queueClaim };
          const sourceUpdatedAt = String(source.updated_at || "").trim();
          if (sourceUpdatedAt && Number.isFinite(Date.parse(sourceUpdatedAt))) {
            queueClaim.source_updated_at = sourceUpdatedAt;
          }
          if (
            typeof source.title === "string" &&
            (source.body === null || typeof source.body === "string") &&
            typeof source.locked === "boolean" &&
            Array.isArray(source.labels)
          ) {
            const labels = [
              ...new Set(
                source.labels
                  .map((label) => String(label?.name || "").trim().toLowerCase())
                  .filter((label) => {
                    if (!label) return false;
                    if (label === "proof: override") return true;
                    if (/^(?:status|rating|proof|merge-risk|impact|issue-rating):/.test(label)) return false;
                    if (/^p[0-3]$/.test(label)) return false;
                    if ([
                      "maturity:stable",
                      "feature: ✨ showcase",
                      "good first issue",
                      "mantis: telegram-visible-proof",
                      "proof: telegram-e2e",
                      "triage: needs-real-behavior-proof",
                      "clawsweeper-recovery-stuck",
                      "no-stale",
                      "stale",
                    ].includes(label)) return false;
                    return !label.startsWith("clawsweeper:") || [
                      "clawsweeper:autofix",
                      "clawsweeper:automerge",
                      "clawsweeper:human-review",
                      "clawsweeper:manual-only",
                      "clawsweeper:bulk-filed",
                    ].includes(label);
                  }),
              ),
            ].sort();
            queueClaim.source_content_revision = crypto
              .createHash("sha256")
              .update(
                JSON.stringify({
                  version: 2,
                  title: source.title,
                  body: source.body || "",
                  locked: source.locked,
                  close_guard_labels: labels,
                }),
              )
              .digest("hex");
          }
          if (process.env.ITEM_KIND === "pull_request") {
            if (/^[0-9a-f]{40}$/.test(headSha)) queueClaim.source_head_sha = headSha;
            if (/^[0-9a-f]{40}$/.test(baseSha)) queueClaim.source_base_sha = baseSha;
            if (typeof pullRequest.draft === "boolean") {
              queueClaim.source_is_draft = pullRequest.draft;
            }
          }
          if (
            process.env.ITEM_KIND !== "pull_request" ||
            !/^[0-9a-f]{40}$/.test(headSha) ||
            !updatedAt
          ) {
            process.stdout.write(JSON.stringify(result));
          } else {
            result.ingress_route = "target_dispatcher";
            result.ingress_fingerprint = crypto
              .createHash("sha256")
              .update(
                JSON.stringify({
                  version: 1,
                  target_repo: String(process.env.TARGET_REPO || "").toLowerCase(),
                  item_number: Number(process.env.ITEM_NUMBER),
                  action: String(process.env.SOURCE_ACTION || ""),
                  head_sha: headSha,
                  updated_at: updatedAt,
                  body: typeof pullRequest.body === "string" ? pullRequest.body : "",
                  label: String(event.label?.name || ""),
                }),
              )
              .digest("hex");
            process.stdout.write(JSON.stringify(result));
          }
          NODE
          )"
          client_payload="$(jq -nc \
            --arg target_repo "$TARGET_REPO" \
            --arg target_branch "$TARGET_BRANCH" \
            --argjson item_number "$ITEM_NUMBER" \
            --arg item_kind "$ITEM_KIND" \
            --arg source_event "$SOURCE_EVENT" \
            --arg source_action "$SOURCE_ACTION" \
            --argjson source_identity "$source_identity_json" \
            --argjson supersedes_in_progress "$SUPERSEDES_IN_PROGRESS" \
            '{target_repo:$target_repo,target_branch:$target_branch,item_number:$item_number,item_kind:$item_kind,source_event:$source_event,source_action:$source_action,supersedes_in_progress:$supersedes_in_progress} + $source_identity')"
          # The App webhook remains an independent delivery route.
          if [ -n "${ACTIONS_ID_TOKEN_REQUEST_URL:-}" ] &&
            [ -n "${ACTIONS_ID_TOKEN_REQUEST_TOKEN:-}" ] &&
            oidc_token="$(curl --fail --silent --show-error --connect-timeout 5 --max-time 15 \
              --header "Authorization: bearer $ACTIONS_ID_TOKEN_REQUEST_TOKEN" \
              --get --data-urlencode "audience=$TARGET_DISPATCH_URL" \
              "$ACTIONS_ID_TOKEN_REQUEST_URL" | jq -er '.value | strings | select(length > 0)')" &&
            [ -n "$oidc_token" ]; then
            echo "::add-mask::$oidc_token"
            direct_body="$RUNNER_TEMP/clawsweeper-direct-intake.json"
            if direct_status="$(curl --silent --show-error --connect-timeout 5 --max-time 20 \
              --request POST \
              --header "authorization: Bearer $oidc_token" \
              --header "content-type: application/json" \
              --data "$client_payload" \
              --output "$direct_body" \
              --write-out '%{http_code}' \
              "$TARGET_DISPATCH_URL")" &&
              [[ "$direct_status" == 2[0-9][0-9] ]]; then
              echo "Queued ClawSweeper intake directly: $(jq -c . "$direct_body" 2>/dev/null || echo '{}')"
              exit 0
            fi
            # Only non-transient 4xx is a deliberate refusal; the App webhook covers it.
            # Timeouts, throttling, and verifier/Worker failures must stay re-runnable.
            if [[ "${direct_status:-}" == 4[0-9][0-9] && "$direct_status" != 408 && "$direct_status" != 429 ]]; then
              echo "::warning::ClawSweeper intake declined this event (HTTP $direct_status); the App webhook route still applies."
              exit 0
            fi
            echo "::error::ClawSweeper intake unavailable (HTTP ${direct_status:-none}); re-run this job after the Worker recovers."
          else
            echo "::error::ClawSweeper OIDC token unavailable; the dispatch job needs id-token: write."
          fi
          exit 1
      - name: Dispatch ClawSweeper comment
        if: >-
          ${{
            github.event_name == 'issue_comment' &&
            steps.comment_filter.outputs.is_command == 'true'
          }}
        env:
          TARGET_REPO: ${{ github.repository }}
          ITEM_NUMBER: ${{ github.event.issue.number }}
          COMMENT_ID: ${{ github.event.comment.id }}
          SOURCE_ACTION: ${{ github.event.action }}
          TARGET_DISPATCH_URL: https://clawsweeper.openclaw.ai/github/target-dispatch
        run: |
          set -euo pipefail
          client_payload="$(jq -nc \
            --arg target_repo "$TARGET_REPO" \
            --argjson item_number "$ITEM_NUMBER" \
            --argjson comment_id "$COMMENT_ID" \
            --arg source_action "$SOURCE_ACTION" \
            '{target_repo:$target_repo,item_number:$item_number,comment_id:$comment_id,source_event:"issue_comment",source_action:$source_action}')"
          # The App webhook remains an independent delivery route.
          if [ -n "${ACTIONS_ID_TOKEN_REQUEST_URL:-}" ] &&
            [ -n "${ACTIONS_ID_TOKEN_REQUEST_TOKEN:-}" ] &&
            oidc_token="$(curl --fail --silent --show-error --connect-timeout 5 --max-time 15 \
              --header "Authorization: bearer $ACTIONS_ID_TOKEN_REQUEST_TOKEN" \
              --get --data-urlencode "audience=$TARGET_DISPATCH_URL" \
              "$ACTIONS_ID_TOKEN_REQUEST_URL" | jq -er '.value | strings | select(length > 0)')" &&
            [ -n "$oidc_token" ]; then
            echo "::add-mask::$oidc_token"
            direct_body="$RUNNER_TEMP/clawsweeper-direct-intake.json"
            if direct_status="$(curl --silent --show-error --connect-timeout 5 --max-time 20 \
              --request POST \
              --header "authorization: Bearer $oidc_token" \
              --header "content-type: application/json" \
              --data "$client_payload" \
              --output "$direct_body" \
              --write-out '%{http_code}' \
              "$TARGET_DISPATCH_URL")" &&
              [[ "$direct_status" == 2[0-9][0-9] ]]; then
              echo "Queued ClawSweeper intake directly: $(jq -c . "$direct_body" 2>/dev/null || echo '{}')"
              exit 0
            fi
            # Only non-transient 4xx is a deliberate refusal; the App webhook covers it.
            # Timeouts, throttling, and verifier/Worker failures must stay re-runnable.
            if [[ "${direct_status:-}" == 4[0-9][0-9] && "$direct_status" != 408 && "$direct_status" != 429 ]]; then
              echo "::warning::ClawSweeper intake declined this event (HTTP $direct_status); the App webhook route still applies."
              exit 0
            fi
            echo "::error::ClawSweeper intake unavailable (HTTP ${direct_status:-none}); re-run this job after the Worker recovers."
          else
            echo "::error::ClawSweeper OIDC token unavailable; the dispatch job needs id-token: write."
          fi
          exit 1

package archive

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"path/filepath"
	"strings"
	"time"
)

func writeLocalModelClassification(ctx context.Context, tx *sql.Tx, input classifyInput, classifier localModelClassifier, result localModelResult, classifiedAt time.Time) (int, error) {
	if err := clearLocalModelObservations(ctx, tx, input.AssetID, classifier.modelID); err != nil {
		return 0, err
	}
	imagePath, _ := input.contentImagePath()
	evidenceID := stableID("evidence", input.AssetID, "content_classification", localModelClassifierSource, classifier.modelID, classifier.promptVersion)
	evidenceJSON, err := jsonText(map[string]any{
		"classifier":              localModelClassifierSource,
		"model_id":                classifier.modelID,
		"model_api":               classifier.api,
		"prompt_version":          classifier.promptVersion,
		"endpoint":                result.Endpoint,
		"network_scope":           "loopback",
		"image_transmitted":       true,
		"transmitted_image_bytes": result.ImageBytes,
		"image_sha256":            result.ImageSHA256,
		"image_extension":         strings.ToLower(filepath.Ext(imagePath)),
		"image_path_class":        input.localPathClass(imagePath),
		"classified_at":           classifiedAt.Format(time.RFC3339Nano),
		"raw_response":            result.RawResponse,
		"parsed_response":         result.Payload,
		"local_only":              true,
		"cloud_transmitted":       false,
	})
	if err != nil {
		return 0, err
	}
	if _, err := tx.ExecContext(ctx, `
insert into evidence_ref(id, asset_id, evidence_kind, source, pointer, value_json)
values (?, ?, ?, ?, ?, ?)
on conflict(id) do update set
  asset_id = excluded.asset_id,
  evidence_kind = excluded.evidence_kind,
  source = excluded.source,
  pointer = excluded.pointer,
  value_json = excluded.value_json
`, evidenceID, input.AssetID, "content_classification", localModelClassifierSource, input.AssetID+"/classification/local_multimodal", evidenceJSON); err != nil {
		return 0, fmt.Errorf("write local model evidence: %w", err)
	}

	written := 0
	for _, observation := range result.Observations {
		valueJSON, err := jsonText(observation.Value)
		if err != nil {
			return written, err
		}
		observationID := stableID("model_observation", input.AssetID, localModelClassifierSource, classifier.modelID, classifier.promptVersion, observation.ObservationType, observation.ValueText)
		if _, err := tx.ExecContext(ctx, `
insert into model_observation(id, asset_id, observation_type, value_text, value_json, confidence, source, model_id, prompt_version, evidence_id)
values (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
`, observationID, input.AssetID, observation.ObservationType, observation.ValueText, valueJSON, observation.Confidence, localModelClassifierSource, classifier.modelID, classifier.promptVersion, evidenceID); err != nil {
			return written, fmt.Errorf("write model observation: %w", err)
		}
		if err := insertObservationFTS(ctx, tx, observationID, input.AssetID, observation.ValueText, strings.Join(nonEmpty(observation.ObservationType, observation.ValueText, localModelClassifierSource, classifier.modelID), " ")); err != nil {
			return written, fmt.Errorf("write model observation fts: %w", err)
		}
		for _, term := range observationTerms(observation) {
			termID := stableID("observation_term", input.AssetID, observationID, term)
			if _, err := tx.ExecContext(ctx, `
insert into observation_term(id, asset_id, observation_id, term, term_type, source, model_id)
values (?, ?, ?, ?, ?, ?, ?)
`, termID, input.AssetID, observationID, term, observation.TermType, localModelClassifierSource, classifier.modelID); err != nil {
				return written, fmt.Errorf("write observation term: %w", err)
			}
		}
		written++
	}
	if err := updateClassificationQueue(ctx, tx, input.QueueID, "content_classified", "local_model_observations", classifiedAt); err != nil {
		return written, err
	}
	return written, nil
}

func writeModelRun(ctx context.Context, tx *sql.Tx, runID string, classifier localModelClassifier, endpoints map[string]struct{}, inputCount, httpRequestAttempts, httpResponses, contentClassified, failures int, completedAt time.Time) error {
	responseEndpoints := sortedEndpointSet(endpoints)
	metadataJSON, err := jsonText(map[string]any{
		"content_classified":         contentClassified,
		"failures":                   failures,
		"model_api":                  classifier.api,
		"requested_endpoint":         classifier.endpointURL,
		"response_endpoints":         responseEndpoints,
		"network_scope":              "loopback",
		"transmits_image_bytes":      true,
		"http_request_attempts":      httpRequestAttempts,
		"http_responses_received":    httpResponses,
		"successful_classifications": contentClassified,
		"cloud_transmitted":          false,
		"local_only":                 true,
	})
	if err != nil {
		return err
	}
	if _, err := tx.ExecContext(ctx, `
insert into model_run(id, source, model_id, prompt_version, started_at, completed_at, input_count, metadata_json)
values (?, ?, ?, ?, ?, ?, ?, ?)
on conflict(id) do update set
  completed_at = excluded.completed_at,
  input_count = excluded.input_count,
  metadata_json = excluded.metadata_json
`, runID, localModelClassifierSource, classifier.modelID, classifier.promptVersion, completedAt.Format(time.RFC3339Nano), completedAt.Format(time.RFC3339Nano), inputCount, metadataJSON); err != nil {
		return fmt.Errorf("write model run: %w", err)
	}
	return nil
}

func clearLocalModelObservations(ctx context.Context, tx *sql.Tx, assetID, modelID string) error {
	if strings.TrimSpace(assetID) == "" {
		return errors.New("asset id is required")
	}
	if _, err := tx.ExecContext(ctx, `
delete from observation_fts
where rowid in (
    select mapped.fts_rowid
    from observation_fts_rowid mapped
    join model_observation model on model.id = mapped.observation_id
    where model.asset_id = ? and model.source = ? and model.model_id = ?
  )
`, assetID, localModelClassifierSource, modelID); err != nil {
		return fmt.Errorf("clear model observation fts: %w", err)
	}
	if _, err := tx.ExecContext(ctx, `
delete from observation_fts_rowid
where observation_id in (
  select id from model_observation
  where asset_id = ? and source = ? and model_id = ?
)
`, assetID, localModelClassifierSource, modelID); err != nil {
		return fmt.Errorf("clear model observation FTS mappings: %w", err)
	}
	if _, err := tx.ExecContext(ctx, `
delete from observation_term
where observation_id in (
    select id from model_observation
    where asset_id = ? and source = ? and model_id = ?
  )
`, assetID, localModelClassifierSource, modelID); err != nil {
		return fmt.Errorf("clear observation terms: %w", err)
	}
	if _, err := tx.ExecContext(ctx, `
delete from model_observation
where asset_id = ? and source = ? and model_id = ?
`, assetID, localModelClassifierSource, modelID); err != nil {
		return fmt.Errorf("clear model observations: %w", err)
	}
	return nil
}

